#!/bin/bash
set -e
kod=0
dnf check-update --quiet > /tmp/aktualizacje.txt || kod=$?
case $kod in
  0)   echo "Brak aktualizacji" ;;
  100) echo "Do aktualizacji: $(grep -c . /tmp/aktualizacje.txt) pakietow" ;;
  *)   echo "Blad dnf (kod $kod)" >&2; exit 1 ;;
esac
$ ./sprawdz.sh
